import { ErrorResponseModel } from "s365-dashboard-v2-file-picker/build/src/swagger-clients/s365-dashboard-v2-api-clients.service";

declare const chrome: any;

export const DashboardServiceUrl = process.env.REACT_APP_DASHBOARD_SERVICE_URL;
export const ExcelRunnerServiceUrl = process.env.REACT_APP_EXCEL_RUNNER_SERVICE_URL;
export const SensitivityStudiesServiceUrl = process.env.REACT_APP_SENSITIVITY_STUDIES_SERVICE_URL;
export const TakeHomeExamServiceUrl = process.env.REACT_APP_TAKE_HOME_EXAM_SERVICE_URL;
export async function OpenDwsimFile(fileUniqueIdentifier: string, accessType: AccessType) {

    if (chrome?.webview?.hostObjects?.filePickerService) {

        const filePickerService = chrome.webview.hostObjects.filePickerService;
        console.log("Opening file with unique identifier:", fileUniqueIdentifier, "and access type:", accessType);
        const resp = await  filePickerService.openFile(fileUniqueIdentifier, accessType);
        console.log("Response from openFile:", resp);
        if (!!resp) {
            const errorMesage = JSON.parse(resp) as ErrorResponseModel;
            return errorMesage;
        }
    } else {
        return { errors: ["filePickerService not initialized."] } as ErrorResponseModel;
    }
    return null;

}

export async function SaveDwsimFile(filename: string, parentUniqueIdentifier: string, filePath: string, conflictAction?: UploadConflictAction) {
    console.log("filePath", filePath);
    if (chrome?.webview?.hostObjects?.filePickerService) {

        const filePickerService = chrome.webview.hostObjects.filePickerService;
        await filePickerService.SaveFile(filename, parentUniqueIdentifier, filePath, conflictAction);
    } else {
        throw "filePickerService not initialized.";
    }

}

export async function CreateFolder(folderName: string, parentUniqueIdentifier: string) {

    if (chrome?.webview?.hostObjects?.filePickerService) {

        const filePickerService = chrome.webview.hostObjects.filePickerService;
        await filePickerService.CreateFolder(folderName, parentUniqueIdentifier);
    } else {
        throw "filePickerService not initialized.";
    }
}

export async function DoesFileAlreadyExists(dashboardServiceUrl: string, userToken: string, filename: string, parentDirectoryUniqueId: string) {
    const postModel: ValidateFileNamesPostModel = {
        fileNames: [filename],
        parentDirectoryUniqueId: parentDirectoryUniqueId
    };
    try {

        const response = await fetch(`${dashboardServiceUrl}/api/files/validate-file-names`, {
            method: "POST",
            headers: {
                "Content-Type": "application/json",
                "Authorization": `Bearer ${userToken}`
            },
            body: JSON.stringify(postModel),
        });
        if (response.status == 200) {
            const responseData = await response.json() as ValidateFileNamesResponseModel;
            if (responseData && responseData.existingFiles?.length > 0) {
                return true;
            } else {
                return false;
            }

        } else {
            const errorMessage = await response.text();
            throw new Error(errorMessage);
        }
    } catch (error) {
        console.log(`An error occurred while checking if file already exists.`, error);
        alert(`An error occurred while checking if file already exists.`);
        throw error;
    }

}


export enum UploadConflictAction {
    Overwrite,
    KeepBoth
}

interface ValidateFileNamesPostModel {
    fileNames?: string[];
    parentDirectoryUniqueId?: string | undefined;
}

export interface ValidateFileNamesResponseModel {
    existingFiles: string[];
    existingDirectories: string[];
}

export enum AccessType {
    ReadOnly,
    Collaboration
}
