import { DashboardServiceUrl, ExcelRunnerServiceUrl, SensitivityStudiesServiceUrl, TakeHomeExamServiceUrl } from "./dwsim.services";

declare const chrome: any;

export interface UrlSettingsResponseModel {
    dashboardServiceUrl: string;
    excelRunnerServiceUrl: string;
    sensitivityStudiesServiceUrl: string;
    takeHomeExamsServiceUrl: string;
    environment: string;
}

export async function getDashboardServiceUrl(accessToken: string): Promise<UrlSettingsResponseModel> {
    const systemService = chrome?.webview?.hostObjects?.systemService;
    if (systemService) {
        const resp = await systemService.getUrlSettings();
        console.log("Loading  url settings from dwsim: ", resp);
        const urlSettingsResp = JSON.parse(resp);
        return urlSettingsResp;
    } else {
        return {
            dashboardServiceUrl: DashboardServiceUrl!,
            excelRunnerServiceUrl: ExcelRunnerServiceUrl!,
            sensitivityStudiesServiceUrl: SensitivityStudiesServiceUrl!,
            takeHomeExamsServiceUrl: TakeHomeExamServiceUrl,
            environment: "Production"
        } as UrlSettingsResponseModel;
    }
}
