import * as React from "react";
import moment from "moment";
var ShowLocalTime = function (props) {
    var dateFormat = props.dateFormat ? props.dateFormat : "DD.MM.YYYY";
    var timeFormat = props.timeFormat ? props.timeFormat : "HH:mm";
    var format = "".concat(dateFormat).concat(props.hideTime ? "" : " ".concat(timeFormat));
    if (props.date) {
        if (!props.multiline) {
            return React.createElement("span", null, moment.utc(moment(props.date).format("YYYY-MM-DD HH:mm:ss")).local().format(format));
        }
        else {
            return React.createElement("span", null,
                moment.utc(moment(props.date).format("YYYY-MM-DD HH:mm:ss")).local().format(dateFormat),
                React.createElement("br", null),
                moment.utc(moment(props.date).format("YYYY-MM-DD HH:mm:ss")).local().format(timeFormat),
                "  ");
        }
    }
    return null;
};
export default ShowLocalTime;
