import * as React from "react";
import { Warning24Regular } from "@fluentui/react-icons";

const ErrorPage: React.FC = () => {
    const browserRoute = `${window.location.pathname}${window.location.search}${window.location.hash}`;

    return <div style={{
        minHeight: "100vh",
        display: "flex",
        alignItems: "center",
        justifyContent: "center",
        padding: "32px",
        background: "linear-gradient(135deg, #f5f7fb 0%, #eef2f8 100%)"
    }}>
        <div style={{
            width: "100%",
            maxWidth: "640px",
            backgroundColor: "#ffffff",
            border: "1px solid #e2e8f0",
            borderRadius: "14px",
            boxShadow: "0 10px 32px rgba(14, 30, 62, 0.12)",
            padding: "40px 36px",
            textAlign: "center"
        }}>
            <div style={{
                display: "flex",
                justifyContent: "center",
                width: "100%",
                marginBottom: "22px"
            }}>
                <img
                    src="/s365-full-logo.png"
                    style={{ width: "220px" }}
                    alt="Simulate 365"
                />
            </div>

            <h1 style={{
                margin: "0 0 10px 0",
                fontSize: "30px",
                lineHeight: 1.2,
                color: "#1f2937",
                display: "flex",
                alignItems: "center",
                justifyContent: "center",
                gap: "10px"
            }}>
                <span style={{
                    display: "inline-flex",
                    alignItems: "center",
                    justifyContent: "center",
                    width: "36px",
                    height: "36px",
                    borderRadius: "999px",
                    backgroundColor: "#fff4e5",
                    color: "#a15c00"
                }}>
                    <Warning24Regular />
                </span>
                Something went wrong
            </h1>

            <p style={{
                margin: "0 0 8px 0",
                fontSize: "16px",
                lineHeight: 1.5,
                color: "#334155"
            }}>
                An unknown error occurred.
            </p>
            <p style={{
                margin: "0",
                fontSize: "16px",
                lineHeight: 1.5,
                color: "#334155"
            }}>
                Please contact support.
            </p>
            <p style={{
                margin: "14px 0 0 0",
                fontSize: "13px",
                lineHeight: 1.4,
                color: "#64748b"
            }}>
                Route: {browserRoute}
            </p>
        </div>
    </div>;
};

export default ErrorPage;
