import React from "react";
import ReactSelect, { ActionMeta, GroupBase, SingleValue, StylesConfig, components } from "react-select";
import { PersonDisplay } from "../person-display/person-display.component";
import { GroupsClient, GroupTableResultModel } from "s365-dashboard-v2-file-picker/build/src/swagger-clients/s365-dashboard-v2-api-clients.service";
import { getDashboardServiceUrl } from "../../../services/dashboard.service";
import axios from 'axios';

export type SelectOption = {
    value: string | number,
    label: string,
    userPrincipalName?: string;
    mail?: string;

}


type UserOwnedGroupPickerProps = {
    userAccessToken: string;
    style?: React.CSSProperties;
    placeholder?: string;
    disabled?: boolean;
    onChange: (selectedOption: SelectOption | undefined) => void;
}

export const UserOwnedGroupPicker: React.FC<UserOwnedGroupPickerProps> = (props) => {

    const [currentValue, setCurrentValue] = React.useState<string>("");
    const [isLoading, setIsloading] = React.useState<boolean>(false);
    const [options, setOptions] = React.useState<SelectOption[]>([]);
    const [groups, setGroups] = React.useState<GroupTableResultModel[]>([]);


  
    const getAxionsInstance = () => {
        return axios.create({
            headers: {
                Authorization: `Bearer ${props.userAccessToken}`
            }
        })
    }
    const getGroups = async () => {
        try {
            setIsloading(true);
            const urlSettings = await getDashboardServiceUrl(props.userAccessToken);
            const axiosInstance = getAxionsInstance();
            const client = new GroupsClient(urlSettings.dashboardServiceUrl, axiosInstance);
            const groupsResp = await client.getUserOwnedGroups();
            const activeGroups = groupsResp?.filter(x => !x.isDeleted) ?? [];
            setGroups(activeGroups);
        } catch (error) {
            console.error("An error occurred while getting user groups", error);
        } finally {
            setIsloading(false);
        }
    }

    React.useEffect(() => { getGroups(); }, []);

    const Option = (props) => {
        const person = props.data as SelectOption;

        return <components.Option {...props}>
            <PersonDisplay id={person.label} name={person.label} userPrincipalName={person.userPrincipalName!} />

        </components.Option>
    }

    const onParametersChanged = async (newOption: SingleValue<SelectOption>, actionMeta: ActionMeta<SelectOption>) => {    
   
        if (actionMeta.action === "select-option" && newOption) {
            props.onChange(newOption);
        } else {
            props.onChange(undefined);
        }
    
}

    React.useEffect(() => {
        updateSuggestions();
    }, [groups]);

    const updateSuggestions = () => {
        const groupOptions = groups?.map((group) => ({ label: group.groupname, value: group.id } as SelectOption));

        setOptions(groupOptions);
    }



    return (
        <div style={{ ...props.style }}>
            <ReactSelect
                isLoading={isLoading}
                isClearable
                placeholder={props.placeholder}
                options={options}
                isDisabled={props.disabled}
                onInputChange={(newValue: string) => { setCurrentValue(newValue); }}
                onChange={onParametersChanged}
                components={{ Option }}
                styles={ContactPickerStyless}
            />
        </div>
    );

}


const ContactPickerStyless: StylesConfig<SelectOption, false, GroupBase<SelectOption>> = {
    control: (styles) => ({ ...styles, minHeight: "30px", borderBottomColor: "var(--colorNeutralStrokeAccessible) !important" }),
    dropdownIndicator: (styles) => ({
        ...styles,
        paddingTop: 5,
        paddingBottom: 5,
    }),
    indicatorSeparator: (styles) => ({
        ...styles,
        display: "none"
    }),
    clearIndicator: (styles) => ({
        ...styles,
        paddingTop: 5,
        paddingBottom: 5,
    }),
    input: (styles) => ({
        ...styles,
        paddingTop: 0,
        paddingBottom: 0,
    }),
    option: (styles) => ({
        ...styles,
        paddingTop: "4px",
        paddingBottom: "4px",
        lineHeight: "16px"
    }),
};

