import { FluentProvider, Spinner, teamsLightTheme } from "@fluentui/react-components";
import { Outlet } from "react-router-dom";
import "./PrivateRoute.styless.scss";
declare const chrome: any;

type PrivateRouteProps = {
    isLoggedIn: boolean,
    isLoading: boolean
}

const PrivateRoute = (props: PrivateRouteProps) => {
    const { isLoading, isLoggedIn } = props;

    const showLoginForm = () => {
        const filePickerService = chrome?.webview?.hostObjects?.filePickerService;
        if (filePickerService) {
            filePickerService.showLoginForm();
        }

    }
    if (!isLoggedIn) {
        return (<FluentProvider theme={teamsLightTheme}>
            <div style={{
                display: "flex",
                flexDirection: "column",
                alignItems: "center",
                justifyContent: "center",
                height: "100vh"
            }}>

                {!isLoading && <div style={{ textAlign: "center", fontSize: "16px" }}>                    
                    <a className="login-link" onClick={(ev) => { ev.preventDefault(); showLoginForm(); }}>
                        <b> Sign in with Simulate 365 account</b></a> to access this feature.
                        </div>}
                {isLoading && <Spinner labelPosition="below" size='huge' label="Loading dashboard..." />}
            </div>
        </FluentProvider>)
    }



    return <Outlet />;
};

export default PrivateRoute;