import React from 'react';
import { HashRouter, Navigate, Route, Routes } from 'react-router-dom';
import { ToastContainer } from 'react-toastify';
import 'react-toastify/dist/ReactToastify.css';
import LoginIntroPage from './pages/login-intro.component';
import OpenDashboardFilePage from './pages/open-dashboard-file.component';
import { FluentProvider, teamsLightTheme } from '@fluentui/react-components';
import PrivateRoute from './routing/PrivateRoute';
import { ShareFilePage } from './pages/share/share-file.page';
import ErrorPage from './pages/error/error.page';
declare const chrome: any;
export const user_token = window.localStorage.getItem("s365_local_user_token");

const logInvalidJwt = (reason: string, token: string | null | undefined, details?: Record<string, unknown>) => {
  const tokenPreview = token ? `${token.slice(0, 10)}...` : null;
  console.warn('[Auth] Invalid JWT token', {
    reason,
    tokenExists: Boolean(token),
    tokenLength: token?.length ?? 0,
    tokenPreview,
    ...details,
  });
};

const isValidJwtToken = (token: string | null | undefined): token is string => {
  if (!token) {
    logInvalidJwt('Token is empty or undefined', token);
    return false;
  }

  if (token.split('.').length !== 3) {
    logInvalidJwt('Token is not in JWT format (header.payload.signature)', token);
    return false;
  }

  try {
    const payloadPart = token.split('.')[1];
    const normalizedPayload = payloadPart.replace(/-/g, '+').replace(/_/g, '/');
    const paddedPayload = normalizedPayload + '='.repeat((4 - (normalizedPayload.length % 4)) % 4);
    const payload = JSON.parse(window.atob(paddedPayload));

    if (typeof payload.exp !== 'number') {
      logInvalidJwt('Token payload does not contain a numeric exp claim', token, { payloadKeys: Object.keys(payload || {}) });
      return false;
    }

    const nowInSeconds = Math.floor(Date.now() / 1000);
    if (payload.exp <= nowInSeconds) {
      logInvalidJwt('Token is expired', token, {
        exp: payload.exp,
        nowInSeconds,
      });
      return false;
    }

    return true;
  } catch (error) {
    logInvalidJwt('Token payload is not valid base64url JSON', token, {
      error: error instanceof Error ? error.message : String(error),
    });
    return false;
  }
};

function App() {

  const [userAccessToken, setUserAccessToken] = React.useState<string | null>(null);
  const [isLoggedIn, setIsLoggedIn] = React.useState<boolean>(false);
  const [isLoading, setIsLoading] = React.useState<boolean>(false);
  React.useEffect(() => {
    onInit();

  }, []);
  const onInit = async () => {
    const token = await getUserToken();
     console.log("token",token);
    if (isValidJwtToken(token)) {
      setIsLoggedIn(true);
      setUserAccessToken(token);
      return;
    }
    console.log("No valid token found, user is not logged in.");
    setIsLoggedIn(false);
    setUserAccessToken(null);
  }

  const getUserToken = async () => {
    setIsLoading(true);    
    console.log("chrome.webview?.hostObjects?.authService", chrome.webview?.hostObjects?.authService);
    let token = !chrome.webview?.hostObjects?.authService ? user_token : undefined;

    if (chrome.webview?.hostObjects?.authService) {

      const authService = chrome.webview.hostObjects.authService;
      try {
        token = await authService.getUserToken();
      } catch (error) {
        console.log("An error occurred while getting user token", error);
        token = "";
      }
    }
    setIsLoading(false);

    // console.log("App.tsx token", token, !!token);
    return token;
  }
 // console.log("userAccessToken",userAccessToken);
//console.log("isLoading,isLoggedIn",isLoading,isLoggedIn);
  return <FluentProvider theme={teamsLightTheme}>
    <HashRouter>  <ToastContainer
      position="top-right"
      autoClose={5000}
      hideProgressBar={true}
      newestOnTop={false}
      closeOnClick
      rtl={false}
      pauseOnFocusLoss
      draggable
      pauseOnHover
    /> <div className="App">
        <Routes>
          <Route path="/" element={<PrivateRoute isLoading={isLoading} isLoggedIn={isLoggedIn} />}>
            <Route index element={<ErrorPage />} />
            <Route path="/filepicker/open" element={userAccessToken && <OpenDashboardFilePage userAccessToken={userAccessToken} />} />
            <Route path="/filepicker/save" element={userAccessToken && <OpenDashboardFilePage userAccessToken={userAccessToken} isSaveDialog={true} />} />
             <Route path="/share/file/:fileUniqueId" element={userAccessToken &&<ShareFilePage userAccessToken={userAccessToken} />} />
            <Route path="*" element={<ErrorPage />} />
          </Route>          
          <Route path="/login/intro" element={<LoginIntroPage />} />
          <Route path="/login/intro/:navigateToLogin" element={<LoginIntroPage />} />
          <Route path="*" element={<Navigate to={"/login/intro"} replace />} />
        </Routes>
      </div> </HashRouter>
  </FluentProvider>;

}

export default App;
