export const getFileExtension = (filename: string) => {
    if (!filename)
        return undefined;

    var filenameArray = filename.split('.');
    if (filenameArray && filenameArray.length > 1) {
        return filenameArray.pop();
    } else {
        return undefined;
    }
}

export const getFileNameWithoutExtension = (filename?: string) => {
    if (!filename) {
        return "";
    }
    const extension = getFileExtension(filename);
    if (!!extension) {
        const nameWithoutExtension = filename.split(`.${extension}`)[0];
        return sanitizeFilename(nameWithoutExtension);
    }
    return "";
}

export const sanitizeFilename = (filename?: string) => {   
  
    const allowedCharacters = /[^a-zA-Z0-9 .\-_]/g;

    // Replace disallowed characters with a space
    return filename?.replace(allowedCharacters, " ");
}