import React from "react";
import ReactSelect, { ActionMeta, GroupBase, SingleValue, StylesConfig, components, createFilter } from "react-select";


import { FilterOptionOption } from "react-select/dist/declarations/src/filters";
import { SelectOption } from "../user-owned-group-picker/user-owned-group-picker.components";
import { ContactResponseModel, ContactsClient } from "s365-dashboard-v2-file-picker/build/src/swagger-clients/s365-dashboard-v2-api-clients.service";
import { PersonDisplay } from "../person-display/person-display.component";
import axios from 'axios';
import { getDashboardServiceUrl } from "../../../services/dashboard.service";


type ContactPickerProps = {
    style?: React.CSSProperties;
    placeholder?: string;
    showOnlyOrganizationMembers?: boolean;
    value?: ContactOption | null;
    inputValue?: string;
    disabled?: boolean;
    userAccessToken: string;
    onInputChange?: (inputValue: string) => void;
    noOptionsMessage?: (data: { inputValue: string }) => string;
    onChange: (selectedOption: ContactOption | undefined) => void;
}

export type ContactOption = SelectOption & {
    userPrincipalName: string;
}
export const ContactPicker: React.FC<ContactPickerProps> = (props) => {

    const [currentValue, setCurrentValue] = React.useState<string>("");
    const [selectedValue, setSelectedValue] = React.useState<ContactOption | null | undefined>(props.value);
    const [isLoading, setIsloading] = React.useState<boolean>(false);
    const [options, setOptions] = React.useState<ContactOption[]>([]);
    const [contacts, setContacts] = React.useState<ContactResponseModel[]>([]);
    React.useEffect(() => { setCurrentValue(props.inputValue ?? ""); }, [props.inputValue]);

    React.useEffect(() => { getContacts(); }, []);

     React.useEffect(() => {
        if (props.value) {            
            const match = options.find(opt => opt.value === props.value?.value);
            setSelectedValue(match || props.value);
        } else {
            setSelectedValue(null);
        }
        console.log("contact picker value changed", props.value);
    }, [props.value, options]);

    const Option = (props) => {
        const person = props.data as ContactOption;

        return <components.Option {...props}>
     <PersonDisplay id={person.value.toString()} name={person.label} userPrincipalName={person.userPrincipalName} />
        </components.Option>
    }
  const getAxionsInstance = () => {
        return axios.create({
            headers: {
                Authorization: `Bearer ${props.userAccessToken}`
            }
        })
    }
    const onParametersChanged = async (newOption: SingleValue<ContactOption>, actionMeta: ActionMeta<ContactOption>) => {
        if (actionMeta.action == "select-option") {
            props.onChange(newOption as ContactOption);
            setSelectedValue(newOption);
             setCurrentValue("");
        } else {
            props.onChange(undefined);
            setSelectedValue(undefined);
        }

    }

    React.useEffect(() => {
        updateSuggestions();

    }, [contacts]);

    const updateSuggestions = () => {
        const availableContacts = contacts.filter(x => x.confirmed !== false && !!x.userInfo);
        const mappedUserOptions = availableContacts.map((user: any) => ({
            value: user.userInfo.id,
            label: user.userInfo.displayName,
            userPrincipalName: user.userInfo.userPrincipalName
        } as ContactOption)) ?? [];


        setOptions(mappedUserOptions);
    }

    const getContacts = async () => {

        try {
            setIsloading(true);
            const urlSettings = await getDashboardServiceUrl(props.userAccessToken);
            const axiosInstance = getAxionsInstance();
            const client = new ContactsClient(urlSettings.dashboardServiceUrl, axiosInstance);
            const contactsResp = await client.getMyContacts(props.showOnlyOrganizationMembers);
            setContacts(contactsResp ?? []);
        } catch (error) {
            console.error("An error occurred while getting contacts", error);
        } finally {
           setIsloading(false);
        }
   

}
console.log("Contact picker value", selectedValue);

const handleInputChange = (newValue: string, { action }: { action: string }) => {
    // Only update inputValue for input-change, not for menu-close or input-blur
    if (action === "input-change") {
        const value= newValue?.trim();
        setCurrentValue(value);
        props.onInputChange?.(value);
    }
    return newValue;
};

const handleBlur = () => {
    // Restore inputValue on blur if needed
    setCurrentValue(currentValue);
};

return <div style={{ ...props.style }}>
    <ReactSelect
        isLoading={isLoading}
        isClearable
        placeholder={props.placeholder}
        options={options}
        value={selectedValue ?? null}
        inputValue={currentValue}
        isDisabled={props.disabled}
        noOptionsMessage={props.noOptionsMessage}
        filterOption={createFilter(filterConfig as any)}
        onInputChange={handleInputChange}
        onBlur={handleBlur}
        onChange={onParametersChanged}
        components={{ Option }}
        styles={ContactPickerStyless} />
</div>

}
const filterConfig = {
    ignoreCase: true,
    matchFrom: 'any',
    stringify: (option: FilterOptionOption<ContactOption>) => { return `${option.label} ${option.data.userPrincipalName}`; }
}
const ContactPickerStyless: StylesConfig<ContactOption, false, GroupBase<ContactOption>> = {
    control: (styles) => ({ ...styles, minHeight: "30px", borderBottomColor: "var(--colorNeutralStrokeAccessible) !important" }),
    dropdownIndicator: (styles) => ({
        ...styles,
        paddingTop: 5,
        paddingBottom: 5,
    }),
    indicatorSeparator: (styles) => ({
        ...styles,
        display: "none"
    }),
    clearIndicator: (styles) => ({
        ...styles,
        paddingTop: 5,
        paddingBottom: 5,
    }),
    input: (styles) => ({
        ...styles,
        paddingTop: 0,
        paddingBottom: 0,
    }),
    option: (styles) => ({
        ...styles,
        paddingTop: "4px",
        paddingBottom: "4px",
        lineHeight: "16px"
    }),
};

