import * as React from "react";
import moment from "moment";
import { DropdownOption } from "../models/shared.models";
import { CollaborationFilePicker, FilePicker } from "s365-dashboard-v2-file-picker";
import { BreadcrumbItem, ErrorResponseModel, FileModel, FileWithBreadcrumbsResponseModel, IFileModel } from "s365-dashboard-v2-file-picker/build/src/swagger-clients/s365-dashboard-v2-api-clients.service";
import { useSearchParams } from "react-router-dom";
import { FilePickerType } from "s365-dashboard-v2-file-picker/build/src/file-picker.component";
import { AccessType, DashboardServiceUrl, DoesFileAlreadyExists, ExcelRunnerServiceUrl, OpenDwsimFile, SaveDwsimFile, SensitivityStudiesServiceUrl, TakeHomeExamServiceUrl, UploadConflictAction } from "../services/dwsim.services";
import { getDashboardServiceUrl, UrlSettingsResponseModel } from "../services/dashboard.service";
import { toast } from "react-toastify";
import { Button, Combobox, Dropdown, Input, Option, Select, Tab, TabList } from "@fluentui/react-components";
import CreateFolderModal from "./create-folder-modal/create-folder-modal.component";
import { FilesUploadConflictModal } from "./FilesUploadConflictModal";
import { Alert } from "@fluentui/react-components/unstable";
import "s365-dashboard-v2-file-picker/build/src/person-display/person-display.styless.css"
import { set } from "react-hook-form";
import nl2br from 'nl2br';
declare const chrome: any;



interface IOpenDashboardFilePageProps {
    userAccessToken: string;
    isSaveDialog?: boolean;

}
interface IOpenDashboardFilePageRouteProps {
    extension?: string;
}


// UrlSettingsResponseModel imported from getDashboardServiceUrl



const OpenDashboardFilePage: React.FC<IOpenDashboardFilePageProps> = (props) => {

    const [selectedFolder, setSelectedFolder] = React.useState<FileWithBreadcrumbsResponseModel>();
    const [isDataLoaded, setIsDataLoaded] = React.useState<boolean>(false);
    const [filename, setFilename] = React.useState<string>('');
    const [selectedFileType, setSelectedFileType] = React.useState<string>("dwxmz");
    const [filterFileTypes, setFilterFileTypes] = React.useState<string[]>(["dwxml", "dwxmz", "xml", "dwcsd", "dwcsd2", "dwrsd", "dwrsd2", "dwruf"]);
    const [showCreateFolderModal, setShowCreateFolderModal] = React.useState<boolean>(false);
    const FilePickerRef = React.useRef<FilePickerType>();
    const [queryParams, setQueryParams] = useSearchParams();
    const [selectedTab, setSelectedTab] = React.useState<string>("my-files");
    const [showCollaborationTab, setShowCollaborationTab] = React.useState<boolean>(false);
    const [isSaveAs, setIsSaveAs] = React.useState<boolean>(false);
    const [isLeavingCollaborationFile, setIsLeavingCollaborationFile] = React.useState<boolean>(false);
    const [leavingCollaborationFileMessage, setLeavingCollaborationFileMessage] = React.useState<string>();

    const [showResolveConflictModal, setShowResolveConflictModal] = React.useState<boolean>(false);
    const [errorMessage, setErrorMessage] = React.useState<string | undefined>(undefined);
    const urlSettings = React.useRef<UrlSettingsResponseModel | null>(null);

    React.useEffect(() => {
        onInit();

    }, []);
    const onInit = async () => {
        console.log("open dashboard file onInit");
        getLeavingCollaborationFileMessage();
        urlSettings.current = await getDashboardServiceUrl(props.userAccessToken);
        await changeFileTypeFilter();
    }

    // getDashboardServiceUrl extracted to services/dwsim.services.ts

    React.useEffect(() => {
        //When we change selected folder using query params
        const selectedFolderOnPicker = FilePickerRef.current?.getSelectedFolder();
        if (selectedFolderOnPicker !== selectedFolder?.file?.uniqueIdentifier) {
            FilePickerRef.current?.getFilesAndFolders();
        }
    }, [selectedFolder]);

    React.useEffect(() => {
        FilePickerRef.current?.getFilesAndFolders();
    }, [filterFileTypes]);

    const changeFileTypeFilter = async () => {
        console.log("props", props);


        console.log("params", queryParams);

        const collaboration = queryParams.get("collaboration");
        if (collaboration) {
            setShowCollaborationTab(true);
        }

        const saveAs = queryParams.get("saveAs");
        if (saveAs && saveAs.toLowerCase() === "true") {
            setIsSaveAs(true);
        }
        const leavingCollaborationFile = queryParams.get("leavingCollaborationFile");
        if (leavingCollaborationFile && leavingCollaborationFile.toLowerCase() === "true") {
            setIsLeavingCollaborationFile(true);
        }

        const directory = queryParams.get("directory");
        if (directory) {
            if (directory && selectedFolder?.file?.uniqueIdentifier !== directory) {
                await getSelectedFolder(directory);
            }
        }
        let fileTypeExtensions: string[] = filterFileTypes;
        const extensions = queryParams.get('extensions');
        console.log("extensions", extensions);
        if (extensions) {
            fileTypeExtensions = extensions.split('_');
        }
        let suggestedFilename = queryParams.get('filename');
        if (suggestedFilename) {
            suggestedFilename = decodeURIComponent(suggestedFilename.replaceAll('+', ' '));
        } else {
            suggestedFilename = '';
        }
        setSelectedFileType(fileTypeExtensions[0]);
        setFilterFileTypes(fileTypeExtensions);
        setFilename(suggestedFilename!);

    }

    const getLeavingCollaborationFileMessage = async () => {
        const filePickerService = chrome?.webview?.hostObjects?.filePickerService;
        const message = await filePickerService?.getLeavingCollaborationFileMessage();
        setLeavingCollaborationFileMessage(message);
    }


    const getSelectedFolder = async (directoryUniqueIdentifier?: string) => {
        if (!directoryUniqueIdentifier) {
            setSelectedFolder(undefined);
            return;
        }
        try {

            const resp = await fetch(`${urlSettings?.current?.dashboardServiceUrl}/api/directories/${directoryUniqueIdentifier}?includeBreadcrumbs=true`, {
                method: 'GET',
                headers: {
                    'Authorization': `Bearer ${props.userAccessToken}`
                }
            });
            const respJson = await resp.json() as FileWithBreadcrumbsResponseModel;
            setSelectedFolder(respJson);

        }
        catch (error) {
            console.log("An error occurred while loading selected Folder with uniqueIdentifier", directoryUniqueIdentifier);
        }
    }



    const selectedFileChanged = async (selectedDocument: FileModel, accessType: AccessType) => {

        const { isSaveDialog } = props;
        console.log("Selected folder", selectedFolder);
        setErrorMessage(undefined);
        if (selectedDocument) {


            if (!isSaveDialog) {
                let filePath = "//Simulate 365 Dashboard";
                if (selectedFolder) {
                    const pathFolders = [...selectedFolder?.breadcrumbItems ?? [], selectedFolder.file!];
                    if (pathFolders.length > 0) {
                        const breadcrumbPath = pathFolders.reduce((x, y) => x + "/" + y.name, '');
                        filePath = `${filePath}${breadcrumbPath}/${selectedDocument.name}`;
                    }

                } else {
                    filePath = `${filePath}/${selectedDocument.name}`;
                }

                const error: ErrorResponseModel | null = await OpenDwsimFile(selectedDocument.uniqueIdentifier!, accessType);
                if (!!error) {
                    const message = (error.errors?.length ?? 0) > 0 ? error.errors![0] : "An error occurred while opening the file.";
                    setErrorMessage(message);
                }

            } else {
                let nameArray = selectedDocument?.name?.split('.');
                if (nameArray && nameArray.length > 1)
                    nameArray?.pop();
                const newFileName = nameArray?.reduce((prev, curr) => prev + curr, "");
                setFilename(newFileName ?? '');
                onSaveFileClick(newFileName);
            }

        }
    }




    const onSaveFileClick = async (fileNameToSave?: string) => {

        if (fileNameToSave && selectedFileType) {

            let fileNameWithExtension = fileNameToSave;
            if (fileNameWithExtension.toUpperCase().indexOf(selectedFileType.toUpperCase()) == -1) {
                fileNameWithExtension = `${fileNameToSave}.${selectedFileType}`
            }
            try {

                const alreadyExists = await DoesFileAlreadyExists(urlSettings?.current?.dashboardServiceUrl!, props.userAccessToken, fileNameWithExtension, selectedFolder?.file?.uniqueIdentifier!);
                console.log("file alreadyExists", alreadyExists);
                if (alreadyExists) {
                    setShowResolveConflictModal(true);
                    return;
                } else {
                    saveFile(fileNameToSave);
                }

            } catch (error) {
                return;
            }

        }
    }
    const saveFile = (fileNameToSave: string, conflictAction?: UploadConflictAction) => {
        let fileNameWithExtension = filename;
        if (!fileNameWithExtension.toUpperCase().endsWith(`.${selectedFileType.toUpperCase()}`)) {
            fileNameWithExtension = `${filename}.${selectedFileType}`
        }
        let filePath = "//Simulate 365 Dashboard";
        if (selectedFolder) {
            const pathFolders = [...selectedFolder?.breadcrumbItems ?? [], selectedFolder.file!];
            if (pathFolders.length > 0) {
                const breadcrumbPath = pathFolders.reduce((x, y) => x + "/" + y.name, '');
                filePath = `${filePath}${breadcrumbPath}/${fileNameWithExtension}`;
            }

        } else {
            filePath = `${filePath}/${fileNameWithExtension}`;
        }
        SaveDwsimFile(fileNameWithExtension, selectedFolder?.file?.uniqueIdentifier!, filePath, conflictAction);
    }






    const dropdownControlledExampleOptions = getDropDownOptions(filterFileTypes);



    return <div style={{ height: '100%', display: 'flex', flexDirection: 'column', padding: "20px" }} >
        {props.isSaveDialog && <div style={{ marginLeft: "30px", marginRight: "30px", marginBottom: "var(--spacingHorizontalMNudge)" }}>
            {isSaveAs && isLeavingCollaborationFile && <Alert intent="warning" className="alert--info-global" style={{ marginBottom: "var(--spacingVerticalL)" }}>
                 <span dangerouslySetInnerHTML={{__html:nl2br(leavingCollaborationFileMessage)}}></span>
            </Alert>}
            <div style={{ display: "flex", marginBottom: "5px", marginTop: "5px" }}>
                <div style={{ flexBasis: "100%" }} >
                    <Input className="input-field--full-width" placeholder="Enter file name here" value={filename} onChange={(ev, data) => setFilename(data.value)} />
                </div>
                <div >
                    <Button appearance="primary" style={{ marginLeft: "10px", minWidth: "100px" }} onClick={() => onSaveFileClick(filename)} >{isSaveAs ? "Save As" : "Save"}</Button>

                </div>

            </div>
            <div style={{ display: "flex", marginBottom: "5px", marginTop: "5px" }} >
                <div style={{ flexBasis: "100%" }}>
                    <Select

                        value={selectedFileType}
                        //@ts-ignore
                        placeholder="Select an option"
                        onChange={(e, option) => { setSelectedFileType(option?.value?.toString() ?? filterFileTypes[0]); }}
                    >
                        {dropdownControlledExampleOptions && dropdownControlledExampleOptions.map((option) => {

                            return <option value={option.key}>{option.text}</option>
                        })}
                    </Select>
                </div>
                <div>
                    <Button style={{ marginLeft: "10px", minWidth: "100px" }} onClick={() => setShowCreateFolderModal(true)} >New Folder</Button>
                </div>
            </div>


            {showCreateFolderModal && <CreateFolderModal
                isOpened={true}
                onFolderCreated={() => { setShowCreateFolderModal(false); FilePickerRef.current?.getFilesAndFolders(); }}
                selectedFolder={selectedFolder}
                onClose={() => setShowCreateFolderModal(false)} />}
        </div>
        }
        <Alert intent="info" style={{ marginBottom: "var(--spacingVerticalMNudge)" }}><span>View and download your files on <b style={{ fontWeight: "700", color: "#3eb489" }}>dashboard.simulate365.com</b></span></Alert>
        {errorMessage && <Alert intent="error" style={{ marginBottom: "var(--spacingVerticalMNudge)" }}>{errorMessage}</Alert>}

        {!props.isSaveDialog && showCollaborationTab && <TabList selectedValue={selectedTab} onTabSelect={(ev, data) => { setSelectedTab(data.value as string); }}>
            <Tab key="my-files" value="my-files" >My files</Tab>
            <Tab key="collaboration" value="collaboration">Collaboration</Tab>
        </TabList>}

        <div className="tab-content">
            {selectedTab == "my-files" && props.userAccessToken && !!urlSettings && !!urlSettings?.current?.dashboardServiceUrl && <FilePicker
                userAccessToken={props.userAccessToken}
                showStudiesCounts
                baseFolder={selectedFolder?.file?.uniqueIdentifier}
                environment={!!urlSettings?.current?.environment && urlSettings?.current?.environment.toLowerCase() !== "production" ? urlSettings?.current?.environment : undefined}
                dashboardServiceUrl={urlSettings?.current?.dashboardServiceUrl}
                excelRunnerServiceUrl={urlSettings?.current?.excelRunnerServiceUrl}
                sensitivityStudiesServiceUrl={urlSettings?.current?.sensitivityStudiesServiceUrl}
                takeHomeExamServiceUrl={urlSettings?.current?.takeHomeExamsServiceUrl}
                defaultFileType={selectedFileType}
                filterFileTypes={filterFileTypes}
                onSelectedFileChanged={(selectedDocument: FileModel) => { console.log("selectedFile changed", selectedDocument); selectedFileChanged(selectedDocument, AccessType.ReadOnly); }}
                onSelectedFolderChanged={(folder) => { console.log("on folder changed", folder); getSelectedFolder(folder?.uniqueIdentifier!); }}
            />}

            {selectedTab == "collaboration" && props.userAccessToken && !!urlSettings && !!urlSettings?.current?.dashboardServiceUrl &&

                <CollaborationFilePicker
                    userAccessToken={props.userAccessToken}
                    baseFolder={selectedFolder?.file?.uniqueIdentifier}
                    environment={!!urlSettings?.current?.environment && urlSettings?.current?.environment.toLowerCase() !== "production" ? urlSettings?.current?.environment : undefined}
                    dashboardServiceUrl={urlSettings?.current?.dashboardServiceUrl}
                    defaultFileType={selectedFileType}
                    filterFileTypes={filterFileTypes}
                    onSelectedFileChanged={(selectedDocument: FileModel) => { console.log("selectedFile changed", selectedDocument); selectedFileChanged(selectedDocument, AccessType.Collaboration); }}
                    onSelectedFolderChanged={(folder) => { console.log("on folder changed", folder); setErrorMessage(undefined); getSelectedFolder(folder?.file.uniqueIdentifier!); }}
                />}
        </div>



        {showResolveConflictModal && <FilesUploadConflictModal
            onSubmit={(conflictAction) => { saveFile(filename, conflictAction); setShowResolveConflictModal(false); }}
            onClose={() => { setShowResolveConflictModal(false); }} />}

    </div>;




}

function getDropDownOptions(fileExtensions: string[]): DropdownOption[] {

    let options: DropdownOption[] = [];

    fileExtensions.forEach(extension => {
        const option = getFileTypeDropdownOption(extension);
        if (option) {
            options.push(option);
        }
    });

    return options;

}

function getFileTypeDropdownOption(extension?: string): DropdownOption | undefined {


    switch (extension) {
        //dwsim default
        case 'dwxmz': return { key: 'dwxmz', text: 'Compressed XML Simulation File (*.dwxmz)' };
        case 'dwxml': return { key: 'dwxml', text: 'XML Simulation File (*.dwxml)' };
        case 'xml': return { key: 'xml', text: 'Mobile XML Simulation File (*.xml)' };
        case 'dwcsd': return { key: 'dwcsd', text: 'Compound Creator Study (*.dwcsd)' };
        case 'dwcsd2': return { key: 'dwcsd2', text: 'Compound Creator Study (*.dwcsd2)' };
        case 'dwrsd': return { key: 'dwrsd', text: 'Regression Study File (*.dwrsd)' };
        case 'dwrsd2': return { key: 'dwrsd2', text: 'Regression Study File (*.dwrsd2)' };
        case 'dwruf': return { key: 'dwruf', text: 'UNIFAC Regression Study File (*.dwruf)' };
        case 'dwund': return { key: 'dwund', text: 'DWSIM System of Units File (*.dwund)' };
        case 'dwrxm': return { key: 'dwrxm', text: 'DWSIM Reactions File (*.dwrxm)' };
        case 'dwrxs': return { key: 'dwrxs', text: 'DWSIM Reactions File (*.dwrxs)' };
        case 'dwasf': return { key: 'dwasf', text: 'DWSIM Assay File (*.dwasf)' };
        case 'dwcdi': return { key: 'dwcdi', text: 'Initial Estimates File (*.dwcdi)' };
        //end of dwsim default
        case 'pfdx': return { key: 'pfdx', text: 'Interchangeable PFD Simulation File (*.pfdx)' };
        case 'h5': return { key: 'h5', text: 'Hierarchical Data Format (*.h5)' };
        case 'xlsx': return { key: 'xlsx', text: 'Excel Workbook (*.xlsx)' };
        case 'docx': return { key: 'docx', text: 'Word Document (*.docx)' };
        case 'odt': return { key: 'odt', text: 'OpenOffice Writer Document (*.odt)' };
        case 'pdf': return { key: 'pdf', text: 'PDF Files (*.pdf)' };
        case 'ods': return { key: 'ods', text: 'OpenOffice Calc SpreadSheet (*.ods)' };
        case 'json': return { key: 'json', text: 'JSON file (*.json)' };
        case 'bmp': return { key: 'bmp', text: 'BMP file (*.bmp)' };
        case 'jpg': return { key: 'jpg', text: 'JPG file (*.jpg)' };
        case 'svg': return { key: 'svg', text: 'SVG file (*.svg)' };
        case 'png': return { key: 'json', text: 'PNG file (*.png)' };
        case 'gif': return { key: 'gif', text: 'GIF file (*.gif)' };
        case 'mov': return { key: 'mov', text: 'MOV file (*.mov)' };
        case 'mp4': return { key: 'mp4', text: 'MP4 file (*.mp4)' };
        case 'mp3': return { key: 'mp3', text: 'MP3 file (*.mp3)' };
        case 'txt': return { key: 'txt', text: 'Text file (*.txt)' };
        case 'py': return { key: 'py', text: 'Python Script File (*.py)' };
        case 'html': return { key: 'html', text: 'HTML file (*.html)' };
        case 'dexpi': return { key: 'dexpi', text: 'DEXPI+ Document (*.dexpi)' };
        default:
            return undefined;
    }

}


export default OpenDashboardFilePage;