import { Button, Dialog, DialogActions, DialogBody, DialogContent, DialogSurface, DialogTitle, DialogTrigger, Input } from "@fluentui/react-components";
import { Field } from "@fluentui/react-components";

import React from "react";
import { useForm } from "react-hook-form";
import { FileWithBreadcrumbsResponseModel } from "s365-dashboard-v2-file-picker/build/src/swagger-clients/s365-dashboard-v2-api-clients.service";
import { Dismiss24Filled } from "@fluentui/react-icons";
import { CreateFolder } from "../../services/dwsim.services";
import { isNonNullChain } from "typescript";

type CreateFolderModalProps = {
    selectedFolder?: FileWithBreadcrumbsResponseModel,
    isOpened?: boolean;
    onClose?: () => void;
    onFolderCreated(): void;
};

type CreateFolderModel = {
    directoryName: string,
    directoryNameExists?: string
}

function CreateFolderModal(props: CreateFolderModalProps) {

    const { register, handleSubmit, watch, setError, clearErrors, setValue, formState: { errors }, reset } = useForm<CreateFolderModel>({

    });


    const onSubmit = async (data: CreateFolderModel) => {
        await CreateFolder(data.directoryName, props.selectedFolder?.file?.uniqueIdentifier!);
        props.onFolderCreated();

    }



    const onModalClose = () => {
        setOpen(false);
        reset();
        if (props.onClose)
            props.onClose();
    }

    React.useEffect(() => {
        setOpen(!!props.isOpened);

    }, [props.isOpened]);

    const [open, setOpen] = React.useState(false);
 const inputRef = React.useRef<HTMLInputElement>(null);

 React.useEffect(()=>{
      
       // console.log("Calling inpuRef focus.");
        inputRef.current?.focus();    
           
       
    },[open]);

    return (<Dialog open={open}  modalType="alert" onOpenChange={(event, data) => {
        reset();

        setOpen(data.open);
        if (data.open == false) {
            if (props.onClose)
                props.onClose();
        }

    }}>
        {props.isOpened == undefined ? <DialogTrigger>
            <Button style={{ margin: "10px 0px" }}>New folder</Button>
        </DialogTrigger> : <></>}
        <DialogSurface>
            <form onSubmit={handleSubmit(onSubmit)}>
                <DialogBody>
                    <DialogTitle action={<Button appearance="transparent" onClick={onModalClose} icon={<Dismiss24Filled />} />}>Create a folder</DialogTitle>
                    <DialogContent className="dialog--content-with-spacing">
                        <Field
                            className="input-field--full-width"
                            validationState={(!!errors.directoryName || !!errors.directoryNameExists) ? "error" : "none"}
                            validationMessage={<span>
                                {errors.directoryName && <>Folder name is required.</>}
                                {errors.directoryNameExists && <>{errors.directoryNameExists.message}</>}
                            </span>

                            }>
                            <Input
                                id="directoryName"
                                 tabIndex={0}
                                  
                                {...register("directoryName", { required: true })}
                                 ref={inputRef}
                                placeholder="Enter your folder name"
                                onChange={(ev, data) => { clearErrors(["directoryNameExists", "directoryName"]); setValue("directoryName", data.value); }}
                            />
                        </Field>

                    </DialogContent>
                    <DialogActions>
                        <Button type="submit" appearance="primary">Create</Button>


                    </DialogActions>
                </DialogBody>
            </form>
        </DialogSurface>
    </Dialog>);
}

export default CreateFolderModal;